import {readFinancialImportCsv} from './financial-import-csv';
import type {HandoffScope} from './cashier-handoff';
export type FinancialStageRequest={id:string;scope:HandoffScope;provider:string;sourceBatch:string;exportHash:string;cutover:string;csv:string;totals:Record<'receivable'|'prepayment'|'security',string>};
export function readFinancialStageStatus(value:unknown,request:FinancialStageRequest){
 validateFinancialStage(request);if(!value||typeof value!=='object')throw Error('Invalid upload status.');const v=value as Record<string,unknown>;
 if(v.schema_version!==1||v.tenant_id!==request.scope.tenant||v.property_id!==request.scope.property||v.actor_id!==request.scope.actor||v.request_id!==request.id||typeof v.found!=='boolean'||typeof v.cancelled!=='boolean'||v.found&&v.cancelled||!v.found&&v.result!==null)throw Error('Upload status does not match the saved request.');
 return {cancelled:v.cancelled,preview:v.found?readFinancialStage(v.result,request):null};
}
export function validateFinancialStage(r:FinancialStageRequest){
 if(!r||!r.scope||!r.totals||![r.id,r.scope.tenant,r.scope.property,r.scope.actor].every(v=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(v))||typeof r.provider!=='string'||!/^[a-z0-9][a-z0-9_-]{0,79}$/.test(r.provider)||typeof r.sourceBatch!=='string'||r.sourceBatch!==r.sourceBatch.trim()||r.sourceBatch.length<1||r.sourceBatch.length>128||/[\x00-\x1f\x7f]/.test(r.sourceBatch)||typeof r.exportHash!=='string'||!/^[0-9a-f]{64}$/.test(r.exportHash)||typeof r.cutover!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(r.cutover)||!Number.isFinite(Date.parse(r.cutover))||new Date(r.cutover).toISOString().slice(0,10)!==r.cutover||typeof r.csv!=='string'||!['receivable','prepayment','security'].every(k=>typeof r.totals[k as keyof typeof r.totals]==='string'&&/^(0|[1-9][0-9]{0,14})$/.test(r.totals[k as keyof typeof r.totals])))throw Error('Check the saved financial import details.');
 return readFinancialImportCsv(r.csv);
}
export function readFinancialStage(value:unknown,request:FinancialStageRequest){
 const source=validateFinancialStage(request);if(!value||typeof value!=='object')throw Error('Invalid migration preview.');const v=value as Record<string,unknown>;
 if(v.schema_version!==1||v.tenant_id!==request.scope.tenant||v.property_id!==request.scope.property||v.actor_id!==request.scope.actor||v.batch_id!==request.id||v.provider!==request.provider||v.source_batch_id!==request.sourceBatch||v.export_sha256!==request.exportHash||v.cutover_date!==request.cutover||v.status!=='staged'||v.financial_records_written!==false||v.ready_to_commit!==false||typeof v.replayed!=='boolean'||typeof v.payload_sha256!=='string'||!/^[0-9a-f]{64}$/.test(v.payload_sha256)||typeof v.source_reconciled!=='boolean'||!Array.isArray(v.rows)||v.rows.length!==source.length||!Array.isArray(v.control_errors)||!v.control_errors.every(e=>typeof e==='string'))throw Error('Migration preview does not match the saved upload.');
 const rows=v.rows.map((item,index)=>{if(!item||typeof item!=='object')throw Error('Invalid preview row.');const row=item as Record<string,unknown>;if(row.row_number!==index+1||row.source_item_id!==source[index].source_item_id||row.category!==source[index].category||row.amount_minor!==source[index].amount_minor||typeof row.valid!=='boolean'||!Array.isArray(row.errors)||!row.errors.every(e=>typeof e==='string')||row.valid!==(row.errors.length===0))throw Error('Migration row does not match the source file.');return {number:index+1,sourceId:source[index].source_item_id,category:source[index].category,amount:source[index].amount_minor,valid:row.valid,errors:row.errors as string[]}});
 const invalid=rows.filter(r=>!r.valid).length;if(v.invalid_rows!==invalid||v.source_reconciled!==(invalid===0&&v.control_errors.length===0))throw Error('Migration reconciliation summary does not match its rows.');
 const totals={receivable:BigInt(0),prepayment:BigInt(0),security:BigInt(0)};for(const row of rows)if(row.valid)totals[row.category]+=BigInt(row.amount);
 for(const category of ['receivable','prepayment','security'] as const){if((v.source_control_totals as Record<string,unknown>)?.[category]!==request.totals[category]||(v.valid_row_totals as Record<string,unknown>)?.[category]!==totals[category].toString())throw Error('Migration totals do not reconcile.');}
 const expectedErrors=(['receivable','prepayment','security'] as const).filter(category=>totals[category].toString()!==request.totals[category]).map(category=>category+'_control_total_mismatch');
 if(JSON.stringify(v.control_errors)!==JSON.stringify(expectedErrors))throw Error('Migration control differences do not match the source totals.');
 return {batch:request.id,reconciled:v.source_reconciled,rows,controlErrors:v.control_errors as string[]};
}
